import re,json,gzip,glob,os
def load(f):
    b=open(f,'rb').read()
    if b[:2]==b'\x1f\x8b': b=gzip.decompress(b)
    return b.decode('utf-8','replace')
out=[]
for f in sorted(glob.glob('2*.html')):
    ts=os.path.basename(f)[:8]
    if ts=='20240813': continue
    d=load(f)
    m=re.search(r'window\.gradio_config\s*=\s*', d)
    rec={'ts':ts,'bytes':len(d)}
    if not m:
        rec['error']='no gradio config'; out.append(rec); continue
    try: obj,_=json.JSONDecoder().raw_decode(d[m.end():])
    except Exception as e: rec['error']=str(e); out.append(rec); continue
    comps={c['id']:c for c in obj.get('components',[])}
    # top-level tabs
    tabs=[c for c in obj.get('components',[]) if c.get('type')=='tabs']
    tlabels=[]
    for t in tabs[:1]:
        for cid in (t.get('props',{}) or {}).get('children',[]) or []:
            ch=comps.get(cid if isinstance(cid,int) else cid)
            if ch and ch.get('type')=='tabitem':
                lb=(ch.get('props') or {}).get('label')
                if lb: tlabels.append(lb)
    models=set()
    for c in obj.get('components',[]):
        p=c.get('props') or {}
        if c.get('type') in ('dropdown','radio','checkboxgroup') and isinstance(p.get('choices'),list):
            for ch in p['choices']:
                mm=re.match(r"\['(.*?)', '.*'\]$", str(ch))
                if mm and 'Overall' not in mm.group(1): models.add(mm.group(1))
    texts=[(c.get('props') or {}).get('value') for c in obj.get('components',[]) if c.get('type')=='markdown']
    texts=[t for t in texts if isinstance(t,str)]
    stats=None
    for t in texts:
        mm=re.search(r'Всего #моделей:\s*\*\*([\d,]+)\*\*.*?Всего #голосов:\s*\*\*([\d,]+)\*\*.*?Последнее обновление:\s*([\d\-.]+)',t,re.S)
        if mm: stats={'models':mm.group(1),'votes':mm.group(2),'updated':mm.group(3)}; break
    title=obj.get('title'); desc=None
    md=re.search(r'<meta name="description" content="([^"]*)"', d)
    if md: desc=md.group(1)
    rec.update(gradio=obj.get('version'), title=title, meta_description=desc,
               n_components=len(comps), tabs=tlabels, n_models=len(models), stats=stats)
    out.append(rec)
json.dump(out,open('/home/user/archive/timeline.json','w'),ensure_ascii=False,indent=1)
for r in out:
    if 'error' in r: print(r['ts'],'ERROR',r['error']); continue
    print(f"{r['ts']} g{r['gradio']:7} comps={r['n_components']:4} models={r['n_models']:3} stats={r['stats']}")
    print("    tabs:", " | ".join(r['tabs']))
